begin;
create table if not exists public.hh_catalog(id uuid primary key default gen_random_uuid(), fid uuid not null references public.hh_families on delete cascade, name text not null check(length(trim(name)) between 1 and 500), quantity text not null default '' check(length(quantity)<=80), category text not null default '' check(length(category)<=80), unique(fid,name));
create unique index if not exists hh_catalog_normalized on public.hh_catalog(fid,lower(trim(name)));
alter table public.hh_catalog enable row level security;
revoke all on public.hh_catalog from public,anon,authenticated;
insert into public.hh_catalog(fid,name,quantity,category) select distinct on (fid,lower(trim(content))) fid,trim(content),quantity,category from public.hh_entries where kind='shopping' order by fid,lower(trim(content)),created_at desc,id on conflict do nothing;
create or replace function public.hh_members_v41(fid uuid) returns table(uid uuid,email text,role text,name text,avatar text) language sql security definer set search_path='' as $$ select m.uid,u.email::text,m.role,p.name,p.avatar from public.hh_memberships m join auth.users u on u.id=m.uid left join public.hh_profiles p on p.uid=m.uid where m.fid=$1 and exists(select 1 from public.hh_memberships a where a.fid=$1 and a.uid=auth.uid()) $$;
create or replace function public.hh_catalog_list(f uuid) returns setof public.hh_catalog language sql security definer set search_path='' as $$ select c.* from public.hh_catalog c where c.fid=f and exists(select 1 from public.hh_memberships m where m.fid=f and m.uid=auth.uid()) order by lower(c.name) $$;
create or replace function public.hh_catalog_save(f uuid,i uuid,n text,q text,c text) returns void language plpgsql security definer set search_path='' as $$ begin if not exists(select 1 from public.hh_memberships m where m.fid=f and m.uid=auth.uid()) then raise exception 'Non autorizzato'; end if; if i is null then insert into public.hh_catalog(fid,name,quantity,category) values(f,trim(n),q,c); else update public.hh_catalog set name=trim(n),quantity=q,category=c where fid=f and id=i; end if; end $$;
create or replace function public.hh_catalog_delete(f uuid,i uuid) returns void language plpgsql security definer set search_path='' as $$ begin if not exists(select 1 from public.hh_memberships m where m.fid=f and m.uid=auth.uid()) then raise exception 'Non autorizzato'; end if; delete from public.hh_catalog where fid=f and id=i; end $$;
create or replace function public.hh_catalog_capture() returns trigger language plpgsql security definer set search_path='' as $$ begin if new.kind='shopping' then insert into public.hh_catalog(fid,name,quantity,category) values(new.fid,trim(new.content),new.quantity,new.category) on conflict do nothing; end if; return new; end $$;
drop trigger if exists hh_catalog_capture on public.hh_entries;
create trigger hh_catalog_capture after insert on public.hh_entries for each row execute function public.hh_catalog_capture();
revoke all on function public.hh_members_v41(uuid),public.hh_catalog_list(uuid),public.hh_catalog_save(uuid,uuid,text,text,text),public.hh_catalog_delete(uuid,uuid),public.hh_catalog_capture() from public,anon,authenticated;
grant execute on function public.hh_members_v41(uuid),public.hh_catalog_list(uuid),public.hh_catalog_save(uuid,uuid,text,text,text),public.hh_catalog_delete(uuid,uuid) to authenticated;
commit;
